import { LitElement, html, render, nothing } from "lit";
import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import { TanStackDevtoolsCore } from "@tanstack/devtools";
import { TanStackDevtools } from "@tanstack/react-devtools";

const probe = (window as any).__probe = { litConnected: 0, litDisconnected: 0, reactMounted: 0, reactCleaned: 0, pluginDestroyed: 0 };
class ProbePanel extends LitElement {
  static properties = { count: {type: Number}, theme: {}, opened: {type: Boolean} };
  declare count: number; declare theme: string; declare opened: boolean;
  constructor(){super();this.count=0;this.theme="";this.opened=false;}
  connectedCallback() { super.connectedCallback(); probe.litConnected++; }
  disconnectedCallback() { super.disconnectedCallback(); probe.litDisconnected++; }
  render() { return html`<p>Lit panel — theme: ${this.theme}</p><button @click=${()=>this.count++}>Lit value: ${this.count}</button>`; }
}
customElements.define("probe-panel", ProbePanel);
function ReactPanel() {
 const [count,setCount] = useState(0);
 useEffect(()=>{probe.reactMounted++;return ()=>{probe.reactCleaned++;};},[]);
 return React.createElement("button",{onClick:()=>setCount(v=>v+1)},"React value: "+count);
}
const mode = new URLSearchParams(location.search).get("mode") ?? "lit";
document.querySelector("#mode")!.textContent=mode;
const host=document.querySelector("#tools") as HTMLDivElement;
let dispose: (()=>void) | undefined;
function mount(){
 if(dispose)return;
 if(mode==="react"){
  const root=createRoot(host);
  root.render(React.createElement(TanStackDevtools,{config:{defaultOpen:true,theme:"light"},eventBusConfig:{connectToServerBus:false},plugins:[{id:"probe-react",name:"React probe",defaultOpen:true,render:React.createElement(ReactPanel)}]}));
  dispose=()=>root.unmount();
 }else{
  let panelHost:HTMLElement|undefined;
  const devtools=new TanStackDevtoolsCore({config:{defaultOpen:true,theme:"light"},eventBusConfig:{connectToServerBus:false},plugins:[{id:"probe-lit",name:"Lit probe",defaultOpen:true,render:(el,props)=>{panelHost=el;render(html`<probe-panel .theme=${props.theme} .opened=${props.devtoolsOpen}></probe-panel>`,el);},destroy:()=>{probe.pluginDestroyed++;if(panelHost)render(nothing,panelHost);}}]});
  devtools.mount(host);
  dispose=()=>devtools.unmount();
 }
}
document.querySelector("#unmount")!.addEventListener("click",()=>{dispose?.();dispose=undefined;});
document.querySelector("#mount")!.addEventListener("click",mount);
mount();
